-- =========================================================
-- DEFTER — SUPABASE POSTGRESQL VERİTABANI ŞEMASI & TOHUM VERİ
-- =========================================================
-- ⚠️ UYARI: Bu dosya SADECE İLK KURULUM içindir.
-- ⚠️ Gerçek veri girildikten sonra bu dosyayı BİR DAHA ASLA çalıştırmayın — DROP TABLE satırları tüm veriyi siler.
-- ⚠️ Yeni tablo/alan eklemek için 'migrations/' klasörü altında ayrı bir migration dosyası oluşturun.
-- =========================================================

-- 1. Mevcut tabloları temizle (Tür uyumsuzluklarını gidermek için temiz kurulum)
DROP TABLE IF EXISTS notifications CASCADE;
DROP TABLE IF EXISTS notes CASCADE;
DROP TABLE IF EXISTS transactions CASCADE;
DROP TABLE IF EXISTS basket_holdings CASCADE;
DROP TABLE IF EXISTS baskets CASCADE;
DROP TABLE IF EXISTS companies CASCADE;
DROP TABLE IF EXISTS ipos CASCADE;
DROP TABLE IF EXISTS ai_history CASCADE;

-- 2. Şirketler & Varlıklar Kütüğü
CREATE TABLE companies (
    id TEXT PRIMARY KEY,
    symbol TEXT NOT NULL UNIQUE,
    name TEXT NOT NULL,
    sector TEXT NOT NULL,
    exchange TEXT NOT NULL, -- BIST, ABD, Avrupa, Emtia, Döviz
    asset_class TEXT NOT NULL, -- hisse, maden, fon, doviz
    index_tag TEXT, -- BIST 30, BIST 100, S&P 500, NASDAQ, Kıymetli Maden, Kur
    price NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    currency TEXT NOT NULL DEFAULT '₺',
    daily_change NUMERIC(6, 2) NOT NULL DEFAULT 0.00,
    pe_ratio NUMERIC(6, 2),
    pb_ratio NUMERIC(6, 2),
    dividend_yield NUMERIC(5, 2) DEFAULT 0.00,
    market_cap TEXT,
    beta NUMERIC(4, 2),
    recommendation TEXT NOT NULL DEFAULT 'TUT', -- AL, SAT, TUT, NÖTR
    in_watchlist BOOLEAN NOT NULL DEFAULT false,
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Sepetler (Portföyler)
CREATE TABLE baskets (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    subtitle TEXT,
    risk_level TEXT NOT NULL DEFAULT 'Orta', -- Düşük, Orta, Yüksek
    risk_color TEXT NOT NULL DEFAULT 'mid',
    total_value NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    total_cost NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    daily_change NUMERIC(6, 2) NOT NULL DEFAULT 0.00,
    total_profit_percent NUMERIC(6, 2) NOT NULL DEFAULT 0.00,
    description TEXT,
    ai_note TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Sepet Varlık Dağılımı (Holdings)
CREATE TABLE basket_holdings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    basket_id TEXT NOT NULL REFERENCES baskets(id) ON DELETE CASCADE,
    company_symbol TEXT NOT NULL REFERENCES companies(symbol) ON DELETE CASCADE,
    weight_percent NUMERIC(5, 2) NOT NULL DEFAULT 0.00,
    quantity NUMERIC(15, 4) NOT NULL DEFAULT 0.0000,
    avg_cost NUMERIC(15, 2) NOT NULL DEFAULT 0.00,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(basket_id, company_symbol)
);

-- 5. Alış & Satış İşlem Defteri (Transactions)
CREATE TABLE transactions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_symbol TEXT NOT NULL REFERENCES companies(symbol) ON DELETE RESTRICT,
    type TEXT NOT NULL, -- BUY, SELL
    quantity NUMERIC(15, 4) NOT NULL,
    price NUMERIC(15, 2) NOT NULL,
    total_amount NUMERIC(15, 2) NOT NULL,
    date DATE NOT NULL DEFAULT CURRENT_DATE,
    note TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 6. Şirkete Özel Notlar
CREATE TABLE notes (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_symbol TEXT NOT NULL REFERENCES companies(symbol) ON DELETE RESTRICT,
    note_text TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 7. Halka Arz Takip Tablosu
CREATE TABLE ipos (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    code TEXT NOT NULL UNIQUE,
    sector TEXT NOT NULL,
    date_range TEXT NOT NULL,
    price_range TEXT NOT NULL,
    offering_size TEXT,
    allocation_method TEXT NOT NULL DEFAULT 'Bireysele Eşit',
    broker TEXT,
    status TEXT NOT NULL DEFAULT 'upcoming', -- active, upcoming, listed
    listed_price NUMERIC(15, 2),
    current_price NUMERIC(15, 2),
    ceiling_days INT DEFAULT 0,
    t1t2 BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 8. Orakul AI Karar & Geri Besleme Geçmişi (Feedback Loop)
CREATE TABLE ai_history (
    id TEXT PRIMARY KEY,
    symbol TEXT,
    type TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    verdict TEXT NOT NULL DEFAULT 'TUT', -- AL, SAT, TUT, GÜÇLÜ AL, DENGELİ, NÖTR
    verdict_tag TEXT NOT NULL,
    verdict_date DATE NOT NULL DEFAULT CURRENT_DATE,
    price_at_verdict NUMERIC(15, 2),
    price_after_period NUMERIC(15, 2),
    outcome_checked_at TIMESTAMPTZ,
    outcome_correct BOOLEAN,
    target_period_days INT DEFAULT 30,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 9. Bildirimler
CREATE TABLE notifications (
    id TEXT PRIMARY KEY,
    type TEXT NOT NULL,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    time TEXT NOT NULL,
    read BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 10. Row Level Security (RLS) - Kişisel Kullanıcı İzinleri
ALTER TABLE companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE baskets ENABLE ROW LEVEL SECURITY;
ALTER TABLE basket_holdings ENABLE ROW LEVEL SECURITY;
ALTER TABLE transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE ipos ENABLE ROW LEVEL SECURITY;
ALTER TABLE ai_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;

-- Strict Fail-Closed RLS Policies:
-- Public/Anon key is explicitly denied read and write access on all tables.
-- All database operations are mediated by the server-side Service Role key (SUPABASE_SERVICE_ROLE_KEY).
CREATE POLICY "No Anon Access on companies" ON companies FOR ALL USING (false);
CREATE POLICY "No Anon Access on baskets" ON baskets FOR ALL USING (false);
CREATE POLICY "No Anon Access on basket_holdings" ON basket_holdings FOR ALL USING (false);
CREATE POLICY "No Anon Access on transactions" ON transactions FOR ALL USING (false);
CREATE POLICY "No Anon Access on notes" ON notes FOR ALL USING (false);
CREATE POLICY "No Anon Access on ipos" ON ipos FOR ALL USING (false);
CREATE POLICY "No Anon Access on ai_history" ON ai_history FOR ALL USING (false);
CREATE POLICY "No Anon Access on notifications" ON notifications FOR ALL USING (false);

-- =========================================================
-- FİYAT ÖNBELLEĞİ (PRICE CACHE) TABLOSU
-- =========================================================
CREATE TABLE IF NOT EXISTS public.price_cache (
    id TEXT PRIMARY KEY,
    data JSONB NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE price_cache ENABLE ROW LEVEL SECURITY;
CREATE POLICY "No Anon Access on price_cache" ON price_cache FOR ALL USING (false);

